pub fn emit_dag_artifact(typed: &Rc<ResolvedGraph>) -> Rc<EmitResult> {
    {
        let modules_json = Rc::new({ let mut __result = Vec::new(); for m in typed.modules.clone().iter().cloned() { __result.push(serialize_typed_module(&m)); } __result }).join(&", ".to_string());
let diagnostics_json = Rc::new({ let mut __result = Vec::new(); for d in typed.diagnostics.clone().iter().cloned() { __result.push(serialize_diagnostic(&d)); } __result }).join(&", ".to_string());
let item_registry_json = Rc::new({ let mut __result = Vec::new(); for k in Rc::new(v2_rt::map_keys(&typed.item_registry.clone())).iter().cloned() { __result.push(json_quote(k.clone())); } __result }).join(&", ".to_string());
let json = v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat("{\n  \"version\": \"0.1.0\",\n  \"modules\": [".to_string(), modules_json), "],\n  \"item_registry_keys\": [".to_string()), item_registry_json), "],\n  \"diagnostics\": [".to_string()), diagnostics_json), "],\n  \"files\": []\n}".to_string());
Rc::new(EmitResult {
    files: Rc::new(vec![Rc::new(TextFile {
    path: "dag-artifact.json".to_string(),
    content: json,
})]),
    diagnostics: Rc::new(vec![]),
})
}
}

pub fn boundary_ref_error(names: Rc<Vec<String>>, ref_name: &String) -> Rc<Vec<Rc<ErrorNode>>> {
    if { let mut __found = false; for n in names.iter().cloned() { if (n.clone().as_str() == ref_name.clone().as_str()) { __found = true; break; } } __found } {
        Rc::new(vec![])
    } else {
        Rc::new(vec![compile_bundle_error(v2_rt::concat(v2_rt::concat("boundary references unknown artifact '".to_string(), ref_name.clone()), "'".to_string()))])
    }
}

pub fn validate_boundaries(plan: &Rc<ArtifactPlan>) -> Rc<Vec<Rc<ErrorNode>>> {
    {
        let names = Rc::new({ let mut __result = Vec::new(); for a in plan.artifacts.clone().iter().cloned() { __result.push(a.name.clone()); } __result });
Rc::new({ let mut __result = Vec::new(); for b in plan.boundaries.clone().iter().cloned() { __result.extend((*v2_rt::concat(boundary_ref_error(names.clone(), &b.from_artifact.clone()), boundary_ref_error(names.clone(), &b.to_artifact.clone()))).iter().cloned()); } __result })
}
}

pub fn emit_from_artifact_plan(typed: Rc<ResolvedGraph>, artifact_plan: &Rc<ArtifactPlan>) -> Rc<EmitResult> {
    {
        if ((artifact_plan.artifacts.clone().len() as i64) == 0) {
            return Rc::new(EmitResult {
    files: Rc::new(vec![]),
    diagnostics: Rc::new(vec![compile_bundle_error("compile_sources planned no artifacts".to_string())]),
})
        }
let boundary_diags = validate_boundaries(&artifact_plan);
if ((boundary_diags.clone().len() as i64) > 0) {
            return Rc::new(EmitResult {
    files: Rc::new(vec![]),
    diagnostics: boundary_diags.clone(),
})
        }
let results = Rc::new({ let mut __result = Vec::new(); for artifact in artifact_plan.artifacts.clone().iter().cloned() { __result.push(emit_artifact(typed.clone(), artifact.clone())); } __result });
let all_files = Rc::new({ let mut __result = Vec::new(); for r in results.clone().iter().cloned() { __result.extend((*r.files.clone()).iter().cloned()); } __result });
let all_diags = Rc::new({ let mut __result = Vec::new(); for r in results.clone().iter().cloned() { __result.extend((*r.diagnostics.clone()).iter().cloned()); } __result });
Rc::new(EmitResult {
    files: all_files,
    diagnostics: all_diags,
})
}
}

pub fn collect_diagnostics(parse_results: Rc<Vec<Rc<ParseResult>>>) -> Rc<Vec<Rc<ErrorNode>>> {
    parse_results.iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<Rc<ErrorNode>>>, pr: Rc<ParseResult>| match pr.error.clone() {
    Some(diag) => v2_rt::rc_list_push(acc.clone(), diag.clone()),
    None => acc.clone(),
})
}

pub fn front_end_sources(sources: Rc<Vec<Rc<SourceFile>>>) -> Rc<FrontendResult> {
    {
        let acc = sources.iter().cloned().fold(Rc::new(FrontendAccum {
    parse_results: Rc::new(vec![]),
    newline_indices: Rc::new(vec![]),
    intern_table: empty_intern_table(),
}), |acc: Rc<FrontendAccum>, s: Rc<SourceFile>| { let acc = Rc::try_unwrap(acc).unwrap_or_else(|rc| (*rc).clone()); {
            let tokens = tokenize(&s.content.clone(), s.path.clone());
let si = build_newline_index(s.path.clone(), &s.content.clone());
let parsed = parse_with_table(&tokens, v2_rt::rc_map_insert(v2_rt::rc_empty_map::<String, Rc<NewlineIndex>>(), si.file.clone(), si.clone()), acc.intern_table);
let pr = parsed.result.clone();
Rc::new(FrontendAccum {
    parse_results: v2_rt::rc_list_push(acc.parse_results, pr.clone()),
    newline_indices: v2_rt::rc_list_push(acc.newline_indices, si.clone()),
    intern_table: parsed.intern_table.clone(),
})
} });
let parse_results = acc.parse_results.clone();
let newline_indices = acc.newline_indices.clone();
let intern_table = acc.intern_table.clone();
let parse_diagnostics = collect_diagnostics(parse_results.clone());
let has_parse_errors = { let mut __found = false; for p in parse_results.clone().iter().cloned() { if (p.error.clone() != None) { __found = true; break; } } __found };
if has_parse_errors {
            Rc::new(FrontendResult {
    graph: None,
    diagnostics: parse_diagnostics,
    newline_indices: newline_indices.clone(),
    intern_table: intern_table,
})
        } else {
            {
                let modules = Rc::new({ let mut __result = Vec::new(); for p in parse_results.clone().iter().cloned() { __result.push(p.module.clone().clone().unwrap()); } __result });
let source_indices = newline_indices.clone().iter().cloned().fold(v2_rt::rc_empty_map::<String, Rc<NewlineIndex>>(), |acc: Rc<HashMap<String, Rc<NewlineIndex>>>, si: Rc<NewlineIndex>| v2_rt::rc_map_insert(acc, si.file.clone(), si.clone()));
let graph = resolve_modules(&modules, &source_indices);
Rc::new(FrontendResult {
    graph: Some(graph.clone()),
    diagnostics: v2_rt::concat(parse_diagnostics, graph.diagnostics.clone()),
    newline_indices: newline_indices.clone(),
    intern_table: intern_table,
})
}
        }
}
}

pub fn resolve_sources(sources: Rc<Vec<Rc<SourceFile>>>) -> Rc<CompileResult> {
    {
        let frontend = front_end_sources(sources);
Rc::new(CompileResult {
    files: Rc::new(vec![]),
    diagnostics: frontend.diagnostics.clone(),
})
}
}

pub fn compile_sources(sources: Rc<Vec<Rc<SourceFile>>>, target: RenderTarget) -> Rc<PipelineResult> {
    {
        let frontend = front_end_sources(sources);
let newline_indices = frontend.newline_indices.clone();
match frontend.graph.clone() {
    None => Rc::new(PipelineResult {
    files: Rc::new(vec![]),
    diagnostics: frontend.diagnostics.clone(),
    complexity: empty_complexity_report(),
    ownership: Rc::new(vec![]),
    artifact_plan: empty_artifact_plan(),
    newline_indices: newline_indices.clone(),
}),
    Some(graph) => {
            let graph_diags = graph.diagnostics.clone();
let resolve_errors = Rc::new({ let mut __result = Vec::new(); for d in graph_diags.iter().cloned() { if is_error_diagnostic(d.diagnostic.clone()) { __result.push(d); } } __result });
if ((resolve_errors.len() as i64) > 0) {
                return Rc::new(PipelineResult {
    files: Rc::new(vec![]),
    diagnostics: frontend.diagnostics.clone(),
    complexity: empty_complexity_report(),
    ownership: Rc::new(vec![]),
    artifact_plan: empty_artifact_plan(),
    newline_indices: newline_indices.clone(),
})
            }
let source_indices = newline_indices.clone().iter().cloned().fold(v2_rt::rc_empty_map::<String, Rc<NewlineIndex>>(), |acc: Rc<HashMap<String, Rc<NewlineIndex>>>, index: Rc<NewlineIndex>| v2_rt::rc_map_insert(acc, index.file.clone(), index.clone()));
let norm = normalize_graph(&graph, source_indices.clone());
let norm_diags = norm.diagnostics.clone();
let norm_errors = Rc::new({ let mut __result = Vec::new(); for d in norm_diags.clone().iter().cloned() { if is_error_diagnostic(d.diagnostic.clone()) { __result.push(d); } } __result });
if ((norm_errors.len() as i64) > 0) {
                return Rc::new(PipelineResult {
    files: Rc::new(vec![]),
    diagnostics: v2_rt::concat(frontend.diagnostics.clone(), norm_diags.clone()),
    complexity: empty_complexity_report(),
    ownership: Rc::new(vec![]),
    artifact_plan: empty_artifact_plan(),
    newline_indices: newline_indices.clone(),
})
            }
let typed = reconcile(norm.graph.clone(), source_indices.clone(), frontend.intern_table.clone());
let typed_diags = typed.diagnostics.clone();
let func_entries = extract_func_entries(typed.clone());
let recursion_ctx = build_recursion_context(typed.clone());
let complexity = build_complexity_report(&func_entries, recursion_ctx, source_indices.clone());
let complexity_diags = complexity_diagnostics(complexity.clone());
let all_diags = v2_rt::concat(typed_diags.clone(), complexity_diags);
let type_errors = Rc::new({ let mut __result = Vec::new(); for d in typed_diags.clone().iter().cloned() { if is_error_diagnostic(d.diagnostic.clone()) { __result.push(d); } } __result });
if ((type_errors.len() as i64) > 0) {
                return Rc::new(PipelineResult {
    files: Rc::new(vec![]),
    diagnostics: v2_rt::concat(v2_rt::concat(frontend.diagnostics.clone(), norm_diags.clone()), all_diags.clone()),
    complexity: complexity.clone(),
    ownership: Rc::new(vec![]),
    artifact_plan: empty_artifact_plan(),
    newline_indices: newline_indices.clone(),
})
            }
let ownership = extract_ownership_proofs(typed.clone());
let ownership_diags = ownership_diagnostics(ownership.clone());
let ownership_errors = Rc::new({ let mut __result = Vec::new(); for d in ownership_diags.clone().iter().cloned() { if is_error_diagnostic(d.diagnostic.clone()) { __result.push(d); } } __result });
if ((ownership_errors.len() as i64) > 0) {
                return Rc::new(PipelineResult {
    files: Rc::new(vec![]),
    diagnostics: v2_rt::concat(v2_rt::concat(v2_rt::concat(frontend.diagnostics.clone(), norm_diags.clone()), all_diags.clone()), ownership_diags.clone()),
    complexity: complexity.clone(),
    ownership: ownership.clone(),
    artifact_plan: empty_artifact_plan(),
    newline_indices: newline_indices.clone(),
})
            }
let artifact_plan = default_artifact_plan(Rc::new({ let mut __result = Vec::new(); for m in typed.modules.clone().iter().cloned() { __result.push(authored_name_at(source_indices.clone(), &m.module.clone())); } __result }), target);
let emit_result = emit_from_artifact_plan(typed.clone(), &artifact_plan);
let emit_files = emit_result.files.clone();
let emit_diags = emit_result.diagnostics.clone();
let emit_errors = Rc::new({ let mut __result = Vec::new(); for d in emit_diags.clone().iter().cloned() { if is_error_diagnostic(d.diagnostic.clone()) { __result.push(d); } } __result });
let final_files = if ((emit_errors.len() as i64) > 0) {
                Rc::new(vec![])
            } else {
                emit_files
            };
Rc::new(PipelineResult {
    files: final_files,
    diagnostics: v2_rt::concat(v2_rt::concat(v2_rt::concat(v2_rt::concat(frontend.diagnostics.clone(), norm_diags.clone()), all_diags.clone()), ownership_diags.clone()), emit_diags.clone()),
    complexity: complexity.clone(),
    ownership: ownership.clone(),
    artifact_plan: artifact_plan.clone(),
    newline_indices: newline_indices.clone(),
})
},
}
}
}

